def semver_sort(versions):
    def parse_version(v):
        # Split on '+' to remove build metadata
        v_no_build = v.split('+')[0]

        # Split on '-' to separate core version and pre-release
        if '-' in v_no_build:
            core_part, pre_part = v_no_build.split('-', 1)
            pre_identifiers = pre_part.split('.')
        else:
            core_part = v_no_build
            pre_identifiers = None

        # Parse core version
        parts = core_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        return (major, minor, patch, pre_identifiers)

    def compare_pre_release(pre1, pre2):
        # pre1 or pre2 can be None
        # A version without pre-release has higher precedence than one with
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:
            return 1  # pre1 > pre2
        if pre2 is None:
            return -1  # pre1 < pre2

        # Compare identifiers left to right
        for i in range(min(len(pre1), len(pre2))):
            id1 = pre1[i]
            id2 = pre2[i]

            # Check if identifiers are all digits
            is_digit1 = id1.isdigit()
            is_digit2 = id2.isdigit()

            if is_digit1 and is_digit2:
                # Both numeric, compare numerically
                num1 = int(id1)
                num2 = int(id2)
                if num1 < num2:
                    return -1
                elif num1 > num2:
                    return 1
            elif is_digit1:
                # Numeric sorts before non-numeric
                return -1
            elif is_digit2:
                # Non-numeric sorts after numeric
                return 1
            else:
                # Both non-numeric, compare by ASCII
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # If all shared identifiers are equal, fewer identifiers sorts first
        if len(pre1) < len(pre2):
            return -1
        elif len(pre1) > len(pre2):
            return 1
        return 0

    def sort_key(v):
        major, minor, patch, pre = parse_version(v)
        # Return tuple for sorting
        # Pre-release None converts to (1, ()) so versions without pre-release sort after
        # Pre-release list converts to (0, tuple) so versions with pre-release sort before
        if pre is None:
            pre_sort = (1, ())
        else:
            pre_sort = (0, tuple(pre))
        return (major, minor, patch, pre_sort)

    # Stable sort using the key function
    return sorted(versions, key=sort_key)

